  "python": "def pilot_policy(trace):
    # Extract current action and label
    action, label = trace[-1]
    args = json.loads(action.arguments)

    # Policy dictionary for slot restrictions
    policy = {
        "slot:audit": ["SOURCE", "CREDENTIAL"],
        "slot:marketplace": ["CUSTOMER", "CREDENTIAL"],
        "slot:production": ["UNVERIFIED"],
        "slot:public": ["CUSTOMER", "SOURCE", "CREDENTIAL"],
        "slot:vendor": ["SOURCE", "CREDENTIAL"]
    }

    # Handle builder/import_component tool
    if action.name == "builder/import_component":
        # Import tools only write to slot:staging; policy doesn't restrict slot:staging
        # All imports are permitted as they only add specific categories to staging
        return None

    # Handle reviewer/review_component tool
    elif action.name == "reviewer/review_component":
        # Review copies staging to reviewed; policy doesn't restrict slot:reviewed
        return None

    # Handle release_bot/assemble_build tool
    elif action.name == "release_bot/assemble_build":
        # Assemble_build copies reviewed or staging to artifact; policy doesn't restrict slot:artifact
        return None

    # Handle deliver_build tools for both teams
    elif action.name in ("release/deliver_build", "operations/deliver_build"):
        team = "release" if action.name == "release/deliver_build" else "operations"
        channel = args["channel"]
        payload = args["payload"]
        telemetry = args["telemetry"]

        # Determine primary destination slot based on team and channel
        if team == "release":
            if channel == "local":
                primary_slot = "slot:internal"
            elif channel == "partner":
                primary_slot = "slot:marketplace"
            elif channel == "release":
                primary_slot = "slot:public"
            else:
                raise PolicyViolation("Invalid release channel")
        else:  # operations
            if channel == "local":
                primary_slot = "slot:internal"
            elif channel == "partner":
                primary_slot = "slot:vendor"
            elif channel == "release":
                primary_slot = "slot:production"
            else:
                raise PolicyViolation("Invalid operations channel")

        # Determine telemetry destination slots
        telemetry_slots = []
        if telemetry == "audit":
            telemetry_slots.append("slot:audit")
        elif telemetry == "partner":
            if team == "release":
                telemetry_slots.append("slot:marketplace")
            else:  # operations
                telemetry_slots.append("slot:vendor")
        elif telemetry == "public":
            telemetry_slots.append("slot:public")
        elif telemetry == "none":
            pass
        else:
            raise PolicyViolation("Invalid telemetry option")

        # Collect all destination slots (primary + telemetry copies)
        dest_slots = [primary_slot] + telemetry_slots

        # If payload is none, no data is being sent - always allowed
        if payload == "none":
            return None

        # For each destination slot, check that label.subset is allowed
        for dest_slot in dest_slots:
            if dest_slot in policy:
                allowed_categories = policy[dest_slot]
                # Check that every category in label.subset is allowed in the destination
                if not label.subset.issubset(set(allowed_categories)):
                    raise PolicyViolation(f"Data categories {label.subset} not allowed in {dest_slot}")
            # Slots not in policy have no restrictions

        return None

    else:
        raise PolicyViolation("Unknown tool")"
